package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.documental.*;import org.springframework.beans.factory.ObjectProvider;import cl.nexbyte.siger.institucional.nucleo.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.io.*;import java.nio.channels.FileChannel;import java.nio.file.*;import java.util.*;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.http.*;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;

@RestController @RequestMapping("/nucleo/comunicaciones/{comunicacion}/documentos")
@org.springframework.context.annotation.Conditional(DocumentosIngresoController.CustodiaDisponible.class)
public class DocumentosIngresoController {
    /** Consultar custodia conservada no necesita habilitar el transporte de recuperación. */
    static final class CustodiaDisponible implements org.springframework.context.annotation.Condition {
        public boolean matches(org.springframework.context.annotation.ConditionContext c,org.springframework.core.type.AnnotatedTypeMetadata ignored){var e=c.getEnvironment();return e.getProperty("institucional.nucleo.habilitado",Boolean.class,false)&&(e.getProperty("institucional.formulario-completo.habilitado",Boolean.class,false)||!e.getProperty("institucional.documentos.directorio","").isBlank());}
    }
    public record Documento(UUID id,String origen,EntregaCompleta.Adjunto original,String representacion,boolean descargable,boolean consultable,boolean administrable,String proteccion,boolean restringible,boolean cuarentena){}
    private final BaseJdbc db;private final AutorizacionDocumental policy;private final ObjectProvider<VisorDocumento> visor;private final ObjectProvider<DocumentosGestion> gestion;private final CatalogoLaboratorio catalog;private final ArchivoInstitucional files;private final RecepcionInstitucionalJdbc receiver;
    public DocumentosIngresoController(BaseJdbc db,NucleoInstitucional core,CatalogoLaboratorio catalog,ArchivoInstitucional files,RecepcionInstitucionalJdbc receiver,ObjectProvider<AutorizacionDocumental> policies,ObjectProvider<VisorDocumento> visor,ObjectProvider<DocumentosGestion> gestion){this.db=db;this.policy=policies.getIfAvailable(()->new AutorizacionNucleo(core));this.catalog=catalog;this.files=files;this.receiver=receiver;this.visor=visor;this.gestion=gestion;}
    private CatalogoLaboratorio.Operador actor(Authentication auth,UUID communication,UUID caso){var a=SesionFuncionario.actual(auth,catalog);policy.contextoIngreso(a,communication,caso);return a;}
    @GetMapping public List<Documento> listar(Authentication auth,@PathVariable UUID comunicacion,@RequestParam(required=false)UUID caso){var actor=actor(auth,comunicacion,caso);if(!receiver.esCompleta(comunicacion))return List.of();var e=receiver.completaRegistrada(comunicacion);return db.sql.queryForList("SELECT id,attachment_id FROM institution_document WHERE communication_id=? AND origin='INGRESO_CIUDADANO' ORDER BY id",comunicacion.toString()).stream().filter(r->{try{policy.documento(actor,caso,UUID.fromString(r.get("id").toString()),"METADATOS");return true;}catch(FalloTecnico denied){if(denied.status==404)return false;throw denied;}}).map(r->{var permisos=policy.permisos(actor,caso,UUID.fromString(r.get("id").toString()));var a=e.adjuntos().stream().filter(f->f.id().toString().equals(r.get("attachment_id"))).findFirst().orElseThrow(()->new FalloTecnico(409));return new Documento(UUID.fromString(r.get("id").toString()),"INGRESO_CIUDADANO",a,representacion(e,a),permisos.descarga(),permisos.contenido(),permisos.administrar(),permisos.clasificacion(),permisos.restringir(),DisponibilidadDocumental.retenido(db,UUID.fromString(r.get("id").toString())));}).toList();}
    private String representacion(EntregaCompleta e,EntregaCompleta.Adjunto a){if(visor.getIfAvailable()!=null&&FormatosDocumento.paginable(a.tipo()))return "PAGINAS";if(!e.comunicacion().path("version").asString().equals("1.1"))return "DESCARGA";return switch(a.tipo()){case "audio/mpeg","audio/ogg","audio/wav","audio/mp4","audio/webm"->"AUDIO";case "video/mp4","video/webm"->"VIDEO";default->"DESCARGA";};}
    @RequestMapping(value={"/{documento}/original","/{documento}/representacion"},method={RequestMethod.GET,RequestMethod.HEAD})
    public ResponseEntity<StreamingResponseBody> bytes(Authentication auth,@PathVariable UUID comunicacion,@PathVariable UUID documento,jakarta.servlet.http.HttpServletRequest request)throws IOException{
        UUID caso=request.getParameter("caso")==null?null:UUID.fromString(request.getParameter("caso"));
        var a=actor(auth,comunicacion,caso);boolean inline=request.getRequestURI().endsWith("/representacion");String accion="DESCARGA"; // Ambas rutas transmiten bytes del original; inline no rebaja el permiso.
        policy.documento(a,caso,documento,accion);DisponibilidadDocumental.contenido(db,documento);var ref=referencia(comunicacion,documento);var delivery=receiver.completaRegistrada(comunicacion);
        if(inline&&!Set.of("AUDIO","VIDEO").contains(representacion(delivery,ref.original())))throw new FalloTecnico(404);
        Path path;try{path=files.verificar(ref.clave(),ref.original());}catch(IOException corrupt){throw new FalloTecnico(409);}
        var d=ref.original();return TransferenciaDocumento.responder(path,d.tamanio(),d.sha256(),d.nombre(),d.tipo(),inline,request,mode->audit(documento,comunicacion,a.id(),mode),()->{policy.revalidarDocumento(a,caso,documento,accion);DisponibilidadDocumental.contenido(db,documento);});
    }
    private void audit(UUID doc,UUID com,String actor,String representation){db.sql.update("INSERT INTO institution_document_access(document_id,communication_id,actor_id,at_ms,representation) VALUES(?,?,?,?,?)",doc.toString(),com.toString(),actor,System.currentTimeMillis(),representation);}
    private DocumentoPrivado referencia(UUID com,UUID doc){
        var e=receiver.completaRegistrada(com);var rows=db.sql.queryForList("SELECT storage_key,created_ms FROM institution_document WHERE id=? AND communication_id=? AND origin='INGRESO_CIUDADANO'",doc.toString(),com.toString());if(rows.isEmpty())throw new FalloTecnico(404);
        var attachment=db.sql.queryForObject("SELECT attachment_id FROM institution_document WHERE id=?",String.class,doc.toString());var a=e.adjuntos().stream().filter(f->f.id().toString().equals(attachment)).findFirst().orElseThrow(()->new FalloTecnico(409));
        return new DocumentoPrivado(doc,com,"INGRESO_CIUDADANO",rows.getFirst().get("storage_key").toString(),a,null,java.time.Instant.ofEpochMilli(((Number)rows.getFirst().get("created_ms")).longValue()));
    }
    private VisorDocumento visor(){var service=visor.getIfAvailable();if(service==null)throw new FalloTecnico(503,"VISTA_NO_DISPONIBLE");return service;}
    private void eventoVista(CatalogoLaboratorio.Operador a,UUID doc,UUID caso,String code){var service=gestion.getIfAvailable();if(service!=null)service.evento(a,doc,caso,null,code);}
    @GetMapping("/{documento}/vista") public VisorDocumento.Vista vista(Authentication auth,@PathVariable UUID comunicacion,@PathVariable UUID documento,@RequestParam(required=false)UUID caso){var a=actor(auth,comunicacion,caso);policy.documento(a,caso,documento,"CONTENIDO");var response=visor().vista(referencia(comunicacion,documento));policy.revalidarDocumento(a,caso,documento,"CONTENIDO");eventoVista(a,documento,caso,"VISTA_CONSULTADA");return new VisorDocumento.Vista(response.representacion(),response.paginas(),response.perfil(),response.originalInline(),policy.permisos(a,caso,documento).descarga());}
    @RequestMapping(value="/{documento}/paginas/{pagina}",method={RequestMethod.GET,RequestMethod.HEAD}) public ResponseEntity<StreamingResponseBody> pagina(Authentication auth,@PathVariable UUID comunicacion,@PathVariable UUID documento,@PathVariable int pagina,@RequestParam(required=false)UUID caso,jakarta.servlet.http.HttpServletRequest request){var a=actor(auth,comunicacion,caso);policy.documento(a,caso,documento,"CONTENIDO");var p=visor().pagina(referencia(comunicacion,documento),pagina);return TransferenciaDocumento.responder(p.path(),p.tamanio(),p.sha256(),"pagina.png","image/png",true,request,mode->eventoVista(a,documento,caso,"PAGINA_SOLICITADA"),()->{policy.revalidarDocumento(a,caso,documento,"CONTENIDO");DisponibilidadDocumental.contenido(db,documento);});}

}
